const $ = (id) => document.getElementById(id);
const status = (t) => ($('status').textContent = t);

uccb.storage.get('vibe').then((v) => { if (v) $('vibe').value = v; });

function show(names) {
  $('list').replaceChildren(...names.map((name) => {
    const li = document.createElement('li');
    const span = document.createElement('span');
    span.textContent = name;
    const use = document.createElement('button');
    use.textContent = 'Use';
    use.onclick = async () => {
      await uccb.card.setFields({ name });
      uccb.ui.toast(`Named the card ${name}`, 'success');
    };
    li.append(span, use);
    return li;
  }));
}

$('go').onclick = async () => {
  const card = await uccb.card.get();
  if (!card) return status('Open a card first.');
  const vibe = $('vibe').value.trim();
  uccb.storage.set('vibe', vibe);
  $('go').disabled = true;
  status('Thinking…');
  try {
    const { text } = await uccb.llm.complete([
      { role: 'system', content: 'You suggest character names. Reply with eight names, one per line, and nothing else.' },
      { role: 'user', content: `The character:\n${card.data.description || card.data.personality || '(no description yet)'}\n\nCurrent name: ${card.data.name || '(none)'}\nWanted style: ${vibe || 'anything that fits'}` },
    ], { label: 'Name ideas' });
    const names = text.split('\n').map((l) => l.replace(/^[\s\d.)*-]+/, '').trim()).filter(Boolean).slice(0, 12);
    show(names);
    status(names.length ? 'Pick one to name the card (undo works).' : 'No names came back.');
  } catch (err) {
    status(err.message);
  } finally {
    $('go').disabled = false;
  }
};
